static lv_obj_t *settings_row_value(lv_obj_t *card, const char *icon,
                                     uint32_t icon_color, const char *label,
                                     const char *value, bool show_arrow)
{
    lv_obj_t *row = make_clean_cont(card);
    lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(row, 12, 0);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);

    /* Icon badge: colored rounded square */
    lv_obj_t *badge = lv_obj_create(row);
    lv_obj_set_size(badge, DM(36), DM(36));
    lv_obj_set_style_radius(badge, RAD_CARD, 0);
    lv_obj_set_style_bg_color(badge, lv_color_hex(icon_color), 0);
    lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
    /* Colored glow — echoes Music cover / Games badge */
    lv_obj_set_style_shadow_width(badge, 8, 0);
    lv_obj_set_style_shadow_color(badge, lv_color_hex(icon_color), 0);
    lv_obj_set_style_shadow_opa(badge, LV_OPA_30, 0);
    lv_obj_set_style_border_width(badge, 0, 0);
    lv_obj_set_style_pad_all(badge, 0, 0);
    lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *ic = lv_label_create(badge);
    lv_label_set_text(ic, icon);
    lv_obj_set_style_text_font(ic, FONT_ICON, 0);
    lv_obj_set_style_text_color(ic, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(ic);

    /* Label */
    lv_obj_t *lb = lv_label_create(row);
    lv_label_set_text(lb, label);
    lv_obj_set_style_text_font(lb, FONT_BODY, 0);
    lv_obj_set_style_text_color(lb, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_flex_grow(lb, 1);

    /* Value text */
    if (value) {
        lv_obj_t *val = lv_label_create(row);
        lv_label_set_text(val, value);
        lv_obj_set_style_text_font(val, FONT_BODY, 0);
        lv_obj_set_style_text_color(val, lv_color_hex(COL_SEC), 0);
        /* Expose the value label so cycle callbacks (Auto-Lock) can update it */
        lv_obj_set_user_data(row, val);
    }

    /* Arrow */
    if (show_arrow) {
        lv_obj_t *arrow = lv_label_create(row);
        lv_label_set_text(arrow, LV_SYMBOL_RIGHT);
        lv_obj_set_style_text_font(arrow, FONT_BODY, 0);
        lv_obj_set_style_text_color(arrow, lv_color_hex(COL_SEC), 0);
    }

    return row;
}

/* Create a settings row with icon, label, and a switch */
static lv_obj_t *settings_row_switch(lv_obj_t *card, const char *icon,
                                      uint32_t icon_color, const char *label,
                                      bool initial_state)
{
    lv_obj_t *row = make_clean_cont(card);
    lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);

    /* Bottom spacer: pushes dock down */
    lv_obj_t *sp_bot = make_clean_cont(content);
    lv_obj_set_size(sp_bot, DM(1), DM(1));
    lv_obj_set_flex_grow(sp_bot, 1);

    /* ══════ NAVIGATION GROUP ══════ */
    g_group = lv_group_create();
    lv_group_set_wrap(g_group, true);

    g_keypad_indev = NULL;
    {
        lv_indev_t *indev = lv_indev_get_next(NULL);
        while (indev) {
            if (lv_indev_get_type(indev) == LV_INDEV_TYPE_KEYPAD) {
                lv_indev_set_group(indev, g_group);
                g_keypad_indev = indev;
                LV_LOG_USER("Keypad indev → group attached");
            }
            indev = lv_indev_get_next(indev);
        }
    }

    /* ══════ DOCK ══════ */
    lv_obj_t *dock = make_clean_cont(scr);
    lv_obj_set_size(dock, lv_pct(100), DOCK_H);
    g_dock = dock;
    create_app_dock(dock);

    /* Clock timer (1s) */
    lv_timer_t *clk_timer = lv_timer_create(clock_update_cb, 1000, NULL);
    lv_timer_set_repeat_count(clk_timer, -1);
    clock_update_cb(NULL);

    /* Weather timer (fetch live data now, then every 10 min) */
    weather_update_cb(NULL);
    lv_timer_t *w_timer = lv_timer_create(weather_update_cb, 600000, NULL);
    lv_timer_set_repeat_count(w_timer, -1);

    /* Idle timer (g_idle_timeout → standby) */
    idle_countdown = g_idle_timeout;
    idle_timer = lv_timer_create(idle_timer_cb, 1000, NULL);
    lv_timer_set_repeat_count(idle_timer, -1);

    LV_LOG_USER("Desktop Mate v4.0 — %dx%d (flex layout, 3-tier fonts)",
                (int)sw, (int)sh);
}

