                                       LV_FREETYPE_FONT_STYLE_NORMAL);
dm_font_body = lv_freetype_font_create("/resource/fonts/MiSans-Normal.ttf",
                                       LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 24,
                                       LV_FREETYPE_FONT_STYLE_NORMAL);
dm_font_label = lv_freetype_font_create("/resource/fonts/MiSans-Normal.ttf",
                                        LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 30,
                                        LV_FREETYPE_FONT_STYLE_NORMAL);
dm_font_caption = lv_freetype_font_create("/resource/fonts/MiSans-Normal.ttf",
                                          LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 14,
                                          LV_FREETYPE_FONT_STYLE_NORMAL);
/* LV_SYMBOL_* fallback → 同字号 montserrat 内置（自带全部符号字形） */
if (dm_font_title)   dm_font_title->fallback   = &lv_font_montserrat_48;
if (dm_font_icon)    dm_font_icon->fallback    = &lv_font_montserrat_36;
if (dm_font_body)    dm_font_body->fallback    = &lv_font_montserrat_24;
if (dm_font_label)   dm_font_label->fallback   = &lv_font_montserrat_30;
if (dm_font_caption) dm_font_caption->fallback = &lv_font_montserrat_14;

